#include HEADER
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
int main(int argc,char**argv){
if(argc!=5)return 2;
int h=std::atoi(argv[1]),w=std::atoi(argv[2]),reps=std::atoi(argv[3]),op=std::atoi(argv[4]);
std::vector<std::vector<int>> a(h,std::vector<int>(w));
for(int i=0;i<h;++i)for(int j=0;j<w;++j)a[i][j]=i*7347+j*131;
std::uint64_t sum=0;auto t=std::chrono::steady_clock::now();
for(int k=0;k<reps;++k){auto b=op==0?rotate_90r(a):(op==1?transpose(a):rotate_90l(a));sum+=b[k%b.size()][k%b[0].size()];}
auto e=std::chrono::steady_clock::now();
std::cout<<std::chrono::duration<double,std::milli>(e-t).count()<<' '<<sum<<'\n';}
